css:
.inv-title {
  text-align: center;
  font-size: 13pt;
  font-weight: bold;
  margin-bottom: 15px;
  font-family: 'InterVariable', system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}
table.inv {
  width: 100%;
  border-collapse: collapse;
  margin-top: 10px;
  font-family: 'InterVariable', system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}
table.inv th, table.inv td {
  border: 1px solid #000;
  padding: 3px;
  font-size: 10pt;
}
.row { margin-top: 4px; }
.sign { margin-top: 40px; }

@media print {
  @page { margin: 15mm; }
}

body, .inv-title, table.inv, table.inv th, table.inv td, .row, .sign {
  font-family: "Times New Roman", Times, serif;
  line-height: 1.2;               /* стабільніша висота рядка */
  -webkit-text-size-adjust: 100%;
}
table.inv { table-layout: fixed; } /* менше “стрибків” колонок */

.print-format, 
.print-format * {
  font-family: "Times New Roman", Times, serif !important;
  line-height: 1.2;
}

.print-format .row {
  margin: 4px 0 !important;   /* твоє значення */
  padding: 0 !important;
}

html:
{%- set assets = frappe.get_all(
    "oiAsset",
    filters={"location": doc.name},
    fields=["inventory_no","asset_name","serial_no","responsible_employee","status","quantity"],
    order_by="asset_name asc"
) -%}

{%- macro person_short(ref) -%}
  {%- if not ref -%}—
  {%- else -%}
    {# тягнемо повне ім'я з oiEmployee або User #}
    {%- set full = frappe.db.get_value("oiEmployee", ref, "full_name") 
                   or frappe.db.get_value("User", ref, "full_name") 
                   or ref -%}
    {%- set parts = (full or "").split() -%}
    {%- if parts and parts|length > 0 -%}
      {%- set surname = parts[0] -%}
      {%- set ns = namespace(ini="") -%}
      {%- for p in parts[1:] -%}
        {%- if p -%}{%- set ns.ini = ns.ini + (p[:1]|upper) + "." -%}{%- endif -%}
      {%- endfor -%}
      {{ surname }} {{ ns.ini }}
    {%- else -%}—
    {%- endif -%}
  {%- endif -%}
{%- endmacro -%}


{%- macro person_name(ref) -%}
  {%- if not ref -%}-{% else -%}
    {%- set nm = frappe.db.get_value("oiEmployee", ref, "full_name") -%}
    {{ nm or frappe.db.get_value("User", ref, "full_name") or ref }}
  {%- endif -%}
{%- endmacro -%}

{%- macro fmt_qty(v) -%}
  {%- if v is not none -%}
    {%- set s = ("%.2f"|format(v)).rstrip('0').rstrip('.') -%}
    {{ s }}
  {%- else -%}-{% endif -%}
{%- endmacro -%}

{%- set ns = namespace(total_qty=0) -%}

<div class="inv-title">ОПИС МАЙНА КАБІНЕТА № {{ doc.room }}</div>

<div class="pf-row">Адреса: {{ doc.building }}, поверх {{ doc.floor or "-" }}</div>
<div class="pf-row">
  Відповідальний по кабінету:
  <b>{{ doc.responsible_name or "-" }}</b>{% if doc.responsible_phone %} ({{ doc.responsible_phone }}){% endif %}
</div>

<table class="inv">
  <thead>
    <tr>
      <th style="width:25px;">№</th>
      <th>Найменування</th>
      <th style="width:50px;">Кіл-ть</th>
      {# об'єднана колонка #}
      <th style="width:200px;">Номери</th>
      <th style="width:140px;">Відповідальний<br/>(МВО)</th>
    </tr>
  </thead>
  <tbody>
    {% for a in assets %}
    {%- set ns.total_qty = ns.total_qty + (a.quantity or 0) -%}
    <tr>
      <td>{{ loop.index }}</td>
      <td>{{ a.asset_name }}</td>
      <td>{{ fmt_qty(a.quantity) }} шт.</td>

      {# одна клітинка, два рядки: інв/сер № #}
      <td class="cell-numbers">
        <div><span class="k">Інв. №:</span> <span class="v">{{ a.inventory_no or "—" }}</span></div>
        <div><span class="k">Сер. №:</span> <span class="v">{{ a.serial_no or "—" }}</span></div>
      </td>

      <td>{{ person_short(a.responsible_employee) }}</td>
    </tr>
    {% else %}
    <tr><td colspan="6" style="text-align:center;">Немає активів у кабінеті</td></tr>
    {% endfor %}
  </tbody>

  {% if assets and assets|length > 0 %}
  <tfoot>
    <tr>
      <th colspan="2" style="text-align:right;">Разом:</th>
      <th>{{ fmt_qty(ns.total_qty) }}</th>
      <th colspan="2"></th>
    </tr>
  </tfoot>
  {% endif %}
</table>

<div class="sign">Підпис відповідального по кабінету: ___________________</div>
